parameters.jsCode:
// One item per configured board, with the public API URL that lists its postings.
// Fetch board asks for the full response, so each board comes back as exactly one
// item (Lever's list is a bare JSON array, which would otherwise split into one item
// per posting), in the same order as these items.
const cfg = $('Job Scout config').first().json;
const URLS = {
  ashby: (b) => `https://api.ashbyhq.com/posting-api/job-board/${b}?includeCompensation=true`,
  greenhouse: (b) => `https://boards-api.greenhouse.io/v1/boards/${b}/jobs?content=true&pay_transparency=true`,
  lever: (b) => `https://api.lever.co/v0/postings/${b}?mode=json`,
};
const lists = { ashby: cfg.ashbyBoards, greenhouse: cfg.greenhouseBoards, lever: cfg.leverBoards };

const out = [];
for (const [ats, boards] of Object.entries(lists)) {
  for (const raw of boards || []) {
    const board = String(raw).trim();
    if (board) out.push({ json: { ats, board, url: URLS[ats](encodeURIComponent(board)) } });
  }
}
return out;

// Closed detection. For each board fetched successfully this scan, an open lead from
// that board whose posting isn't in today's list is closed: closed_at = now, whatever
// its status. A board whose fetch failed closes nothing. Nothing is sent about it; a
// closed lead is no longer judged or sent. If the posting comes back, Save lead clears
// closed_at.
const now = new Date().toISOString();

// Same check as Normalize postings: did this board's fetch return a posting list?
function fetched(ats, response) {
  const body = response && !response.error ? response.body : undefined;
  return ats === 'lever' ? Array.isArray(body) : Boolean(body && Array.isArray(body.jobs));
}

// Fetch board returns exactly one item per Board list item, in the same order.
const boards = $('Board list').all().map((i) => i.json);
const ok = new Set();
$('Fetch board').all().forEach((item, i) => {
  const b = boards[i];
  if (b && fetched(b.ats, item.json)) ok.add(b.ats + ':' + b.board);
});
const seen = new Set($('Normalize postings').all().map((i) => i.json.lead_key));

return $input.all()
  .map((i) => i.json)
  .filter((r) => r.lead_key && !r.closed_at && ok.has(r.ats + ':' + r.board) && !seen.has(r.lead_key))
  .map((r) => ({ json: { id: r.id, lead_key: r.lead_key, closed_at: now } }));

// The Jev requests whose first try failed (Ask Jev returned no answers), for one
// more try in Ask Jev again. Ask Jev returns one item per request, in order.
const responses = $('Ask Jev').all();
return $('Build Jev requests').all()
  .filter((req, i) => !(responses[i] && responses[i].json && responses[i].json.answers))
  .map((req) => ({ json: req.json }));

// The crash alert: which step failed and the error. n8n runs this path when a published
// run of this workflow fails, because the workflow has an Error Trigger and no other
// error workflow is set (see the Crash alert note).
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const execution = $json.execution || {};
const error = execution.error || ($json.trigger && $json.trigger.error) || {};
const step = (error.node && error.node.name) || execution.lastNodeExecuted || 'an unknown step';
let message = String(error.message || 'no error message').replace(/\s+/g, ' ').trim();
if (message.length > 500) message = message.slice(0, 500) + '…';
const started = (execution.executionContext && execution.executionContext.triggerNode) || {};
const what = started.type === 'n8n-nodes-base.scheduleTrigger' ? 'scan'
  : started.name ? '"' + started.name + '" run' : 'run';

const lines = ['Job Scout ' + what + ' failed at ' + esc(step) + ': ' + esc(message)];
if (execution.url) lines.push('Execution: ' + esc(execution.url));
return [{ json: { text: lines.join('\n'), silent: false } }];
